"""The ``pennywise`` command."""

import argparse
import csv
import io
import json
import os
import sys
from typing import List, Optional

from . import __version__
from .core import (
    Entry,
    ParseError,
    balance,
    by_category,
    by_month,
    filter_entries,
    format_amount,
    format_entry,
    parse,
    parse_amount,
    parse_category,
    parse_date,
    parse_line,
)

EXIT_OK = 0
EXIT_LEDGER = 1
EXIT_USAGE = 2


class _CannotRead(Exception):
    pass


def _date_arg(text: str):
    try:
        return parse_date(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="pennywise",
        description="Read a plain-text household ledger and tell you where the money went.",
    )
    parser.add_argument("--version", action="version", version=f"%(prog)s {__version__}")
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    p = sub.add_parser("balance", help="print the total of all entries")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("summary", help="print totals per category or month")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--by", choices=["category", "month"], default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("list", help="print matching entries, oldest first")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--category", metavar="C")
    p.add_argument("--since", metavar="DATE", type=_date_arg)
    p.add_argument("--until", metavar="DATE", type=_date_arg)
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("add", help="append an entry to the ledger")
    p.add_argument("file", metavar="FILE")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")

    p = sub.add_parser("export", help="print entries as CSV")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--format", choices=["csv"], default="csv")

    return parser


def _read_text(path: str) -> str:
    try:
        if path == "-":
            data = sys.stdin.buffer.read()
        else:
            with open(path, "rb") as fh:
                data = fh.read()
        return data.decode("utf-8-sig")
    except (OSError, UnicodeDecodeError) as exc:
        raise _CannotRead(f"cannot read {path!r}: {exc}") from None


def _sorted(entries: List[Entry]) -> List[Entry]:
    return sorted(entries, key=lambda e: e.date)  # stable: same day keeps file order


def _entry_dict(e: Entry) -> dict:
    return {
        "date": e.date.isoformat(),
        "category": e.category,
        "amount": format_amount(e.amount),
        "note": e.note,
    }


def _cmd_balance(args, entries) -> str:
    total = format_amount(balance(entries))
    if args.json:
        return json.dumps({"balance": total}) + "\n"
    return total + "\n"


def _cmd_summary(args, entries) -> str:
    groups = by_month(entries) if args.by == "month" else by_category(entries)
    names = sorted(groups)
    if args.json:
        return json.dumps({k: format_amount(groups[k]) for k in names}) + "\n"
    return "".join(f"{k}  {format_amount(groups[k])}\n" for k in names)


def _cmd_list(args, entries) -> str:
    selected = _sorted(
        filter_entries(entries, category=args.category, since=args.since, until=args.until)
    )
    if args.json:
        return json.dumps([_entry_dict(e) for e in selected]) + "\n"
    return "".join(format_entry(e) + "\n" for e in selected)


def _cmd_export(args, entries) -> str:
    buf = io.StringIO()
    writer = csv.writer(buf, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in _sorted(entries):
        writer.writerow([e.date.isoformat(), e.category, format_amount(e.amount), e.note])
    return buf.getvalue()


def _cmd_add(args) -> str:
    """Validate and append; returns the written line. Raises ValueError / _CannotRead."""
    try:
        date = parse_date(args.date)
        category = parse_category(args.category)
        amount = parse_amount(args.amount)
    except ValueError as exc:
        raise ValueError(f"invalid entry: {exc}") from None
    if "\n" in args.note or "\r" in args.note:
        raise ValueError("invalid entry: the note must be a single line")
    note = args.note.strip()
    line = format_entry(Entry(date, category, amount, note))
    # The line must read back as exactly this entry.
    if parse_line(line) != Entry(date, category, amount, note):
        raise ValueError(f"invalid entry: {line!r} would not read back correctly")

    path = args.file
    try:
        prefix = ""
        if os.path.exists(path):
            with open(path, "rb") as fh:
                fh.seek(0, os.SEEK_END)
                if fh.tell() > 0:
                    fh.seek(-1, os.SEEK_END)
                    if fh.read(1) not in (b"\n", b"\r"):
                        prefix = "\n"
        with open(path, "a", encoding="utf-8", newline="") as fh:
            fh.write(prefix + line + "\n")
    except OSError as exc:
        raise _CannotRead(f"cannot write {path!r}: {exc}") from None
    return line + "\n"


def _error(message: str) -> None:
    print(f"pennywise: error: {message}", file=sys.stderr)


def main(argv: Optional[List[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    argv = list(argv)

    parser = _build_parser()
    # `add` takes free-form values (e.g. a negative amount or a note starting
    # with "-"), so stop option parsing after the command name.
    if argv and argv[0] == "add" and not (len(argv) > 1 and argv[1] in ("-h", "--help")):
        rest = argv[1:]
        if rest and rest[0] == "--":
            rest = rest[1:]
        argv = ["add", "--"] + rest

    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else EXIT_USAGE

    try:
        if args.command == "add":
            output = _cmd_add(args)
        else:
            entries = parse(_read_text(args.file))
            handler = {
                "balance": _cmd_balance,
                "summary": _cmd_summary,
                "list": _cmd_list,
                "export": _cmd_export,
            }[args.command]
            output = handler(args, entries)
    except _CannotRead as exc:
        _error(str(exc))
        return EXIT_USAGE
    except ParseError as exc:
        name = "<stdin>" if args.file == "-" else args.file
        _error(f"{name}: {exc}")
        return EXIT_LEDGER
    except ValueError as exc:
        _error(str(exc))
        return EXIT_LEDGER

    try:
        sys.stdout.write(output)
        sys.stdout.flush()
    except BrokenPipeError:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    return EXIT_OK


if __name__ == "__main__":
    sys.exit(main())
